SELECT EXISTS (
    SELECT 1 FROM TB_EXTERNAL_QUERY
    WHERE QUERY_CODE = #{queryCode}
      AND DELETED_AT IS NULL

        AND QUERY_ID != #{excludeId}

)


WHERE q.OWNER_TYPE = 'MANAGER'
  AND q.USE_YN = 'Y'
  AND (
      q.OWNER_USERNAME = #{username}

          OR q.OWNER_DEPT_CODE IN

              #{code}


  )

ORDER BY q.SORT_ORDER, q.QUERY_NAME

WHERE q.USE_YN = 'Y' AND ( q.OWNER_TYPE = 'GLOBAL' OR (q.OWNER_TYPE = 'USER' AND q.OWNER_USERNAME = #{username}) OR (q.OWNER_TYPE = 'MANAGER' AND ( q.OWNER_USERNAME = #{username}
OR q.OWNER_DEPT_CODE IN
#{code}
)) )
ORDER BY CASE q.OWNER_TYPE WHEN 'GLOBAL' THEN 1 WHEN 'MANAGER' THEN 2 WHEN 'USER' THEN 3 END, q.SORT_ORDER, q.QUERY_NAME


WHERE q.QUERY_CODE = #{queryCode}
  AND q.OWNER_TYPE = #{ownerType}

      AND q.OWNER_USERNAME = #{ownerUsername}

mapper.update:
UPDATE TB_EXTERNAL_QUERY
SET
    LAST_EXECUTED_AT = #{lastExecutedAt},
    LAST_RESULT_COUNT = #{lastResultCount}
WHERE QUERY_ID = #{queryId}
  AND DELETED_AT IS NULL

