SELECT COALESCE(MAX(SORT_ORDER), 0)
FROM TB_EXTERNAL_QUERY
WHERE OWNER_TYPE = #{ownerType}

      AND OWNER_USERNAME = #{ownerUsername}

  AND DELETED_AT IS NULL
